#[verus::spec]
fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    // Precondition: The input vector must have a non-negative length.
    // Requires: v.len() >= 0
    assert!(v.len() >= 0);
    
    let n = v.len();
    // Invariant: The matrix will have n rows, each of length n.
    let mut matrix = Vec::with_capacity(n);
    
    // Loop invariant: At the start of each iteration, matrix has i rows created.
    for i in 0..n {
        // Ensure that i is within bounds of the vector v.
        assert!(i < n);
        matrix.push(create_row(&v, i));
    }
    
    // Postcondition: The resulting matrix has n rows and each row has n elements.
    // Ensures: matrix.len() == n && matrix.iter().all(|row| row.len() == n)
    assert!(matrix.len() == n);
    for row in &matrix {
        assert!(row.len() == n);
    }
    
    matrix
}

#[verus::spec]
fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    // Precondition: The index i must be within the bounds of the vector v.
    // Requires: i < v.len()
    assert!(i < v.len());
    
    let n = v.len();
    // Invariant: The row will have n elements initialized to 0.0.
    let mut row = vec![0.0; n]; // Create a row filled with 0.0
    row[i] = v[i]; // Set the diagonal element
    
    // Postcondition: The row has n elements and the i-th element is set to v[i].
    // Ensures: row.len() == n && row[i] == v[i]
    assert!(row.len() == n);
    assert!(row[i] == v[i]);
    
    row
}

